// Converts a recalculated Επιχειρησιακό_Αρχείο_NNN.xlsx into a seed SQL file
// with the same shape as seed/0100_migrated_data.sql, so the later seeds
// (0200-0203, which look projects up by code) still apply on top of it.
//
// Usage:
//   node scripts/workbook-to-seed.cjs <workbook.xlsx> <out.sql>
//
// The workbook must have been recalculated and saved by Excel first (cached
// formula results are read for the "Πληρωτέο Ποσό" column). The output holds
// real financial data -- write it under seed/local/, which is gitignored.
//
// Mapping choices mirror 0100 (generated by tools/migrate_workbook.py):
//   * negative amounts (credit notes) flip direction and are stored positive
//   * recurring rows stay a single ledger row; 0201 turns the Q004 AADE
//     settlements into instalment plans
//   * every row is scope 'business'; AADE rows keep origin 'manual' so the
//     AADE fingerprint uniqueness rule does not apply to migrated history

const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const JSZip = require("jszip");
const ExcelJS = require("exceljs");

// Spyros' org id from 0100 -- used when the database has no org yet.
const ORG_ID = "bdad8677-f30f-5ee1-8da6-a8193b0b69b0";
const ORG = "(select org_id from _kansha_ctx)";

function uuid5(name) {
  const h = crypto.createHash("sha1").update("kansha-workbook:" + name).digest();
  h[6] = (h[6] & 0x0f) | 0x50;
  h[8] = (h[8] & 0x3f) | 0x80;
  const x = h.subarray(0, 16).toString("hex");
  return `${x.slice(0, 8)}-${x.slice(8, 12)}-${x.slice(12, 16)}-${x.slice(16, 20)}-${x.slice(20, 32)}`;
}

const q = (v) => (v == null || v === "" ? "null" : `'${String(v).replace(/'/g, "''")}'`);
const n = (v) => (v == null || v === "" || Number.isNaN(Number(v)) ? "null" : String(Math.round(Number(v) * 100) / 100));
const round2 = (v) => Math.round(Number(v || 0) * 100) / 100;

function cell(ws, r, c) {
  let v = ws.getRow(r).getCell(c).value;
  if (v && typeof v === "object" && !(v instanceof Date)) {
    v = v.result ?? (v.richText ? v.richText.map((t) => t.text).join("") : v.text ?? null);
  }
  if (v instanceof Date) return v.toISOString().slice(0, 10);
  if (typeof v === "string") return v.trim() === "" ? null : v.trim();
  return v ?? null;
}

// Category code exactly as 0100 derived it: 'Άδειες & Μελέτες' -> 'ΆΔΕΙΕΣ_AND_ΜΕΛΈΤΕΣ'.
const categoryCode = (name) => name.replace(/&/g, "AND").toUpperCase().replace(/\s+/g, "_");

const afmOrNull = (v) => {
  if (v == null) return null;
  const s = String(v).replace(/\D/g, "").padStart(9, "0");
  return /^[0-9]{9}$/.test(s) && s !== "000000000" ? s : null;
};

async function loadWorkbook(file) {
  // exceljs crashes on this workbook's cell comments; drop the comment
  // relationships in memory (the file on disk is never modified).
  const zip = await JSZip.loadAsync(fs.readFileSync(file));
  for (const name of Object.keys(zip.files)) {
    if (/^xl\/worksheets\/_rels\/.*\.rels$/.test(name)) {
      const xml = await zip.file(name).async("string");
      zip.file(name, xml.replace(/<Relationship [^>]*(comments|vmlDrawing|threadedComment)[^>]*\/>/g, ""));
    }
  }
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.load(await zip.generateAsync({ type: "nodebuffer" }));
  return wb;
}

async function main() {
  const [src, out] = process.argv.slice(2);
  if (!src || !out) {
    console.error("usage: node scripts/workbook-to-seed.cjs <workbook.xlsx> <out.sql>");
    process.exit(1);
  }
  const wb = await loadWorkbook(src);
  const sql = [];
  const report = { unmappedProjects: new Set(), unmappedCategories: new Set(), unmappedAccounts: new Set(), skipped: [] };
  const emit = (s) => sql.push(s);

  emit(`-- Generated by scripts/workbook-to-seed.cjs from ${path.basename(src)} -- review before applying.`);
  emit(`-- Contains real financial data: keep under seed/local/ (gitignored).`);
  emit(`-- Every reference is looked up by natural key (project code, category code,`);
  emit(`-- account name, contact ΑΦΜ/name), so this applies to an empty database or`);
  emit(`-- on top of a copy of the live one; ledger rows are matched on legacy_excel_id.`);
  emit("begin;\n");
  emit(`insert into orgs (id, name, own_afm)\nselect ${q(ORG_ID)}, 'Η επιχείρησή μου', '000000000'\nwhere not exists (select 1 from orgs);\n`);
  // The org to load into: Spyros' org id if present, else the org that already
  // holds the most ledger rows, else the oldest.
  emit(
    `create temp table _kansha_ctx on commit drop as\nselect coalesce(\n  (select id from orgs where id = ${q(ORG_ID)}),\n  (select org_id from transactions group by org_id order by count(*) desc limit 1),\n  (select id from orgs order by created_at limit 1)\n) as org_id;\n`,
  );

  // --- Ρυθμίσεις: projects (col 10), categories (col 3), opening-balance date
  const rs = wb.getWorksheet("Ρυθμίσεις");
  const openingDate = cell(rs, 28, 3);
  const projectNames = {
    Q000_GENERAL: "Γενικά εταιρείας",
    Q001_ILIOUPOLI_P15_RESIDENCES: "Ηλιούπολη",
    Q002_VOULIAGMENI_309: "Βουλιαγμένη",
    Q003_LAZARAKI32_GLYFADA: "Λαζαράκη 32, Γλυφάδα",
    Q004_AGIOU_KWNSTANTINOU20_GLYFADA: "Αγ. Κωνσταντίνου 20, Γλυφάδα",
    Q005_LEGRENA: "Λεγρενά",
    Q006_KAVOURI_AKTIS2: "Καβούρι, Ακτής 2",
    Q007_KOLONAKI_KARNEADOU37: "Κολωνάκι, Καρνεάδου 37",
  };
  const projects = {};
  let order = 0;
  for (let r = 4; r <= 40; r++) {
    const code = cell(rs, r, 10);
    if (!code || !/^Q\d{3}_/.test(code)) continue;
    projects[code] = `(select id from projects where org_id = ${ORG} and code = ${q(code)})`;
    emit(
      `insert into projects (org_id, code, display_name, sort_order)\nvalues (${ORG}, ${q(code)}, ${q(projectNames[code] ?? code)}, ${order++})\non conflict (org_id, code) do nothing;\n`,
    );
  }
  // cost_treatment as migration 0020 sets it -- on a fresh database that
  // migration runs before any category exists, so the seed must carry it.
  const treatment = {
    ΥΛΙΚΆ: "capex", ΕΡΓΑΤΙΚΆ: "capex", ΥΠΕΡΓΟΛΆΒΟΙ: "capex", ΕΞΟΠΛΙΣΜΌΣ: "capex", ΜΕΤΑΦΟΡΙΚΆ: "capex",
    ΆΔΕΙΕΣ_AND_ΜΕΛΈΤΕΣ: "capex", ΑΓΟΡΆ_ΑΚΙΝΉΤΟΥ: "capex", ΑΜΟΙΒΉ_ΜΕΣΙΤΕΊΑΣ: "capex",
    ΕΝΟΊΚΙΑ_AND_ΜΙΣΘΏΜΑΤΑ: "rent", ΛΕΙΤΟΥΡΓΙΚΆ: "opex", ΑΜΟΙΒΉ_ΔΙΑΧΕΊΡΙΣΗΣ: "opex", ΛΟΓΙΣΤΙΚΆ_AND_ΝΟΜΙΚΆ: "opex",
    ΤΡΑΠΕΖΙΚΆ: "financing", ΦΌΡΟΙ_AND_ΡΥΘΜΊΣΕΙΣ: "tax", ΕΝΦΙΑ: "tax",
    ΠΏΛΗΣΗ_ΑΚΙΝΉΤΟΥ: "income", ΈΣΟΔΑ_ΦΙΛΟΞΕΝΊΑΣ: "income", ΑΝΑΧΡΈΩΣΗ_ΚΌΣΤΟΥΣ: "income", ΡΕΥΣΤΟΠΟΊΗΣΗ_ΠΕΡΙΟΥΣΊΑΣ: "income",
  };
  const categories = {};
  for (let r = 4; r <= 22; r++) {
    const name = cell(rs, r, 3);
    if (!name) continue;
    const code = categoryCode(name);
    categories[name] = `(select id from categories where org_id = ${ORG} and code = ${q(code)})`;
    // An existing classification wins: only fill cost_treatment where unset.
    emit(
      `insert into categories (org_id, code, name, is_financing, cost_treatment)\nvalues (${ORG}, ${q(code)}, ${q(name)}, false, ${q(treatment[code] ?? null)})\non conflict (org_id, code) do update set cost_treatment = coalesce(categories.cost_treatment, excluded.cost_treatment);\n`,
    );
  }
  // The rent-substitute child category 0020 creates (0201 needs it).
  emit(
    `insert into categories (org_id, code, name, kind, scope, parent_id, cost_treatment, sort_order)\nvalues (${ORG}, 'ΡΥΘΜΊΣΕΙΣ_ΑΝΤΊ_ΜΙΣΘΏΜΑΤΟΣ', 'Ρυθμίσεις ΑΑΔΕ αντί μισθώματος',\n        'expense', 'business', ${categories["Ενοίκια & Μισθώματα"] ?? "null"}, 'rent_substitute', 0)\non conflict (org_id, code) do nothing;\n`,
  );
  const personalCategory = `(select id from categories where org_id = ${ORG} and code = 'ΠΡΟΣΩΠΙΚΆ_ΈΞΟΔΑ')`;
  emit(
    `insert into categories (org_id, code, name, kind, scope)\nvalues (${ORG}, 'ΠΡΟΣΩΠΙΚΆ_ΈΞΟΔΑ', 'Προσωπικά έξοδα', 'expense', 'personal')\non conflict (org_id, code) do nothing;\n`,
  );

  // --- Λογαριασμοί: accounts, assets, expected income, private loans
  const ls = wb.getWorksheet("Λογαριασμοί");
  const accounts = {};
  for (let r = 4; r <= 9; r++) {
    const name = cell(ls, r, 1);
    if (!name) continue;
    accounts[name] = `(select id from accounts where org_id = ${ORG} and name = ${q(name)})`;
    const kind = name === "Μετρητά" ? "cash" : "bank";
    const scope = cell(ls, r, 5) === "Εταιρικός" ? "corporate" : "personal";
    emit(
      `insert into accounts (org_id, name, kind, owner_scope, is_liquid, opening_balance, opening_balance_date, notes)\nvalues (${ORG}, ${q(name)}, '${kind}', '${scope}', true, ${n(cell(ls, r, 2))}, ${q(openingDate)}, ${q(cell(ls, r, 6))})\non conflict (org_id, name) do update\n  set opening_balance = excluded.opening_balance, opening_balance_date = excluded.opening_balance_date, notes = excluded.notes;\n`,
    );
  }
  const assetCategory = (name) =>
    /χρυσ/i.test(name) ? "metal" : /κρυπτ/i.test(name) ? "crypto" : /ακίνητ/i.test(name) ? "property" : /ρολόι/i.test(name) ? "watch" : /μηχαν/i.test(name) ? "vehicle" : null;
  for (let r = 14; r <= 21; r++) {
    const name = cell(ls, r, 1);
    const value = cell(ls, r, 2);
    if (!name || typeof value !== "number") continue;
    emit(
      `insert into assets (id, org_id, name, category, estimated_value, ownership_pct, owner_scope, state, notes)\nvalues (${q(uuid5("asset:" + name))}, ${ORG}, ${q(name)}, ${q(assetCategory(name))}, ${n(value)}, ${n(cell(ls, r, 3) ?? 1)}, '${cell(ls, r, 5) === "Εταιρικός" ? "corporate" : "personal"}', 'held', ${q(cell(ls, r, 6))})\non conflict (id) do update set estimated_value = excluded.estimated_value, ownership_pct = excluded.ownership_pct, notes = excluded.notes;\n`,
    );
  }
  for (let r = 26; r <= 29; r++) {
    const source = cell(ls, r, 1);
    const amount = cell(ls, r, 2);
    if (!source || typeof amount !== "number") continue;
    const notes = cell(ls, r, 6);
    emit(
      `insert into expected_income (id, org_id, source, amount, certainty, expected_month, creates_liability, notes)\nvalues (${q(uuid5("expected:" + source))}, ${ORG}, ${q(source)}, ${n(amount)}, '${cell(ls, r, 3) === "Βέβαιο" ? "certain" : "probable"}', ${q(cell(ls, r, 4))}, ${/δάνει/i.test(notes || "")}, ${q(notes)})\non conflict (id) do update set amount = excluded.amount, certainty = excluded.certainty, expected_month = excluded.expected_month, notes = excluded.notes;\n`,
    );
  }
  for (let r = 36; r <= 40; r++) {
    const lender = cell(ls, r, 1);
    const principal = cell(ls, r, 2);
    if (!lender || typeof principal !== "number") continue;
    const rate = cell(ls, r, 4);
    emit(
      `insert into liabilities (id, org_id, lender, kind, principal, interest_rate, maturity_date, state, owner_scope, terms)\nvalues (${q(uuid5("liability:" + lender))}, ${ORG}, ${q(lender)}, 'private', ${n(principal)}, ${typeof rate === "number" ? n(rate) : 0}, ${q(cell(ls, r, 3))}, 'disbursed', 'personal', ${q(cell(ls, r, 6))})\non conflict (id) do update set principal = excluded.principal, maturity_date = excluded.maturity_date, terms = excluded.terms;\n`,
    );
  }

  // --- Επαφές: every contact, keyed on ΑΦΜ when there is one
  const cs = wb.getWorksheet("Επαφές");
  const contactsByAfm = {};
  const contactsByName = {};
  const kindOf = (t) => (!t ? null : /πελάτ/i.test(t) && /προμηθ/i.test(t) ? "both" : /πελάτ/i.test(t) ? "client" : /προμηθ/i.test(t) ? "supplier" : /δημόσ|αρχή|εφορ/i.test(t) ? "authority" : null);
  const addContact = (name, afm, kind, phone, email) => {
    if (contactsByAfm[afm] || contactsByName[name]) return;
    const ref = afm
      ? `(select id from contacts where org_id = ${ORG} and afm = ${q(afm)})`
      : `(select id from contacts where org_id = ${ORG} and name = ${q(name)} order by created_at limit 1)`;
    if (afm) contactsByAfm[afm] = ref;
    contactsByName[name] = ref;
    // An existing contact keeps its own name/details; only gaps are filled.
    emit(
      afm
        ? `insert into contacts (org_id, name, afm, kind, phone, email)\nvalues (${ORG}, ${q(name)}, ${q(afm)}, ${q(kind)}, ${q(phone)}, ${q(email)})\non conflict (org_id, afm) where afm is not null and afm <> '' do update\n  set kind = coalesce(contacts.kind, excluded.kind), phone = coalesce(contacts.phone, excluded.phone), email = coalesce(contacts.email, excluded.email);\n`
        : `insert into contacts (org_id, name, kind, phone, email)\nselect ${ORG}, ${q(name)}, ${q(kind)}, ${q(phone)}, ${q(email)}\nwhere not exists (select 1 from contacts where org_id = ${ORG} and name = ${q(name)});\n`,
    );
  };
  for (let r = 4; r <= cs.rowCount; r++) {
    const name = cell(cs, r, 1);
    if (!name) continue;
    addContact(String(name), afmOrNull(cell(cs, r, 2)), kindOf(cell(cs, r, 3)), cell(cs, r, 4), cell(cs, r, 5));
  }

  // --- Κινήσεις
  const ks = wb.getWorksheet("Κινήσεις");
  const statusMap = { Πληρωμένο: "paid", Εκκρεμεί: "pending", Προγραμματισμένο: "scheduled", Ακυρωμένο: "cancelled" };
  const originMap = { "Τραπεζικό αρχείο": "bank_file" };
  let txCount = 0;
  const totals = { income: 0, expense: 0 };
  const recurring = [];
  for (let r = 4; r <= ks.rowCount; r++) {
    const txDate = cell(ks, r, 1);
    const net0 = cell(ks, r, 10);
    if (!txDate) {
      if (cell(ks, r, 8)) report.skipped.push(`γραμμή ${r}: χωρίς ημερομηνία — «${String(cell(ks, r, 8)).slice(0, 50)}»`);
      continue;
    }
    let direction = cell(ks, r, 9) === "Έσοδο" ? "income" : "expense";
    let net = round2(net0);
    let vat = round2(cell(ks, r, 11));
    let wh = round2(cell(ks, r, 12));
    if (net < 0) {
      direction = direction === "income" ? "expense" : "income";
      net = -net;
      vat = Math.abs(vat);
      wh = Math.abs(wh);
    }
    const gross = round2(net + vat - wh);
    const status = statusMap[cell(ks, r, 15)] ?? "pending";
    const originLabel = cell(ks, r, 16);
    const paidOn = cell(ks, r, 2) ?? (status === "paid" ? txDate : null);
    const name = cell(ks, r, 4);
    const afm = afmOrNull(cell(ks, r, 5));
    if (name && !contactsByName[name] && !(afm && contactsByAfm[afm])) addContact(String(name), afm, null, null, null);
    const contactId = (afm && contactsByAfm[afm]) || (name && contactsByName[name]) || null;
    const projectCode = cell(ks, r, 6);
    const categoryName = cell(ks, r, 7);
    const accountName = cell(ks, r, 14);
    if (projectCode && !projects[projectCode]) report.unmappedProjects.add(projectCode);
    if (categoryName && !categories[categoryName]) report.unmappedCategories.add(categoryName);
    if (accountName && !accounts[accountName]) report.unmappedAccounts.add(accountName);
    const hasInvoice = vat > 0 || wh > 0 || originLabel === "AADE";
    const notes = [cell(ks, r, 18), originLabel ? `Προέλευση: ${originLabel}` : null, cell(ks, r, 19) === "Ναι" ? `Επαναλαμβανόμενο: ${cell(ks, r, 20) ?? "?"} δόσεις, πληρωμένες ${cell(ks, r, 21) ?? 0}` : null]
      .filter(Boolean)
      .join(" · ");

    emit(
      `insert into transactions (
  id, org_id, tx_date, paid_on, due_date, contact_id, counterparty_afm, counterparty_name,
  project_id, category_id, account_id, direction, scope, status, origin,
  gross_amount, net_amount, vat_amount, withholding_amount, has_invoice,
  invoice_number, description, notes, legacy_excel_id
) values (
  ${q(uuid5("tx:" + path.basename(src) + ":" + r))}, ${ORG}, ${q(txDate)}, ${q(paidOn)}, ${q(cell(ks, r, 3))},
  ${contactId ?? "null"}, ${q(afm)}, ${q(name)},
  ${projects[projectCode] ?? "null"}, ${categories[categoryName] ?? "null"}, ${accounts[accountName] ?? "null"}, '${direction}',
  'business', '${status}', '${originMap[originLabel] ?? "manual"}',
  ${gross}, ${net}, ${vat}, ${wh}, ${hasInvoice},
  ${q(cell(ks, r, 17))}, ${q(cell(ks, r, 8))}, ${q(notes || null)}, ${q("kiniseis-row-" + r)}
)
on conflict (org_id, legacy_excel_id) where legacy_excel_id is not null do update set
  tx_date = excluded.tx_date, paid_on = excluded.paid_on, due_date = excluded.due_date,
  status = excluded.status, account_id = excluded.account_id, direction = excluded.direction,
  gross_amount = excluded.gross_amount, net_amount = excluded.net_amount,
  vat_amount = excluded.vat_amount, withholding_amount = excluded.withholding_amount,
  description = excluded.description, notes = excluded.notes;\n`,
    );
    txCount++;
    if (status === "paid") totals[direction] += gross;
    if (cell(ks, r, 19) === "Ναι" && cell(ks, r, 20)) {
      recurring.push({
        row: r, txDate, desc: String(cell(ks, r, 8)), project: projectCode, net, vat, wh,
        count: Number(cell(ks, r, 20)), paid: Number(cell(ks, r, 21) || 0), base: Number(cell(ks, r, 37) || 0),
      });
    }
  }

  // --- Καθημερινά: personal cash spending from the opening-balance month on.
  // The workbook subtracts exactly these from Μετρητά (Λογαριασμοί!C9); card
  // spending on Πειραιώς is NOT subtracted there (its formula looks for an
  // account literally named "Πειραιώς"), so it is left out here too.
  const ds = wb.getWorksheet("Καθημερινά");
  const openingMonth = openingDate.slice(0, 7);
  const dayAfterOpening = new Date(Date.parse(openingDate) + 86400000).toISOString().slice(0, 10);
  let dailyCount = 0;
  let dailyTotal = 0;
  for (let r = 4; r <= ds.rowCount; r++) {
    const month = cell(ds, r, 2);
    const amount = cell(ds, r, 4);
    if (!month || month < openingMonth || cell(ds, r, 6) !== "Μετρητά" || typeof amount !== "number") continue;
    const note = cell(ds, r, 8) ? String(cell(ds, r, 8)) : "";
    // Last dd/mm/yyyy in the note ("01–22/08/2026" -> 22/08/2026); else the 1st.
    const m = [...note.matchAll(/(\d{2})\/(\d{2})\/(\d{4})/g)].pop();
    let date = m ? `${m[3]}-${m[2]}-${m[1]}` : `${month}-01`;
    if (date <= openingDate) date = dayAfterOpening; // the workbook counts the whole opening month
    emit(
      `insert into transactions (
  id, org_id, tx_date, paid_on, account_id, category_id, direction, scope, status, origin,
  gross_amount, net_amount, description, notes, legacy_excel_id
) values (
  ${q(uuid5("daily:" + r))}, ${ORG}, ${q(date)}, ${q(date)}, ${accounts["Μετρητά"]}, ${personalCategory}, 'expense', 'personal', 'paid', 'manual',
  ${n(amount)}, ${n(amount)}, ${q(cell(ds, r, 3))}, ${q(note || null)}, ${q("kathimerina-row-" + r)}
)
on conflict (org_id, legacy_excel_id) where legacy_excel_id is not null do update set
  tx_date = excluded.tx_date, paid_on = excluded.paid_on, gross_amount = excluded.gross_amount,
  net_amount = excluded.net_amount, description = excluded.description, notes = excluded.notes;\n`,
    );
    dailyCount++;
    dailyTotal += amount;
  }

  emit("commit;");
  fs.mkdirSync(path.dirname(out), { recursive: true });
  fs.writeFileSync(out, sql.join("\n"));

  // --- Second file, applied AFTER 0200-0203: recurring rows become instalment
  // plans with their paid instalments marked. 0201 already created the three
  // Q004 AADE plans (matched on Α/Α); every other recurring row gets a plan
  // here and is adopted as instalment #1, the same way 0201 does it.
  // Instalments inside the opening balance ("Δόσεις εντός βάσης") are marked
  // paid on the opening date so they do not move the balance a second time.
  const plans = ["-- Generated by scripts/workbook-to-seed.cjs -- apply after seed/0200-0203.", "begin;\n"];
  const kindOf2 = (d) => (/ενοίκιο/i.test(d) ? "rent" : /ρύθμιση/i.test(d) ? "third_party_tax_settlement" : /λογιστ/i.test(d) ? "supplier" : "other");
  for (const p of recurring) {
    const aa = (p.desc.match(/Α\/Α\s*([0-9]+)/) || [])[1];
    const planMatch = aa
      ? `p.label like ${q("%Α/Α " + aa + "%")}`
      : `p.id = ${q(uuid5("plan:" + p.row))}`;
    if (!aa) {
      plans.push(
        `insert into installment_plans (id, org_id, label, direction, scope, project_id, category_id, account_id,
  amount_per_installment, vat_per_installment, withholding_per_installment, frequency, first_due_date,
  installment_count, obligation_kind, status, notes)
select ${q(uuid5("plan:" + p.row))}, t.org_id, ${q(p.desc)}, t.direction, t.scope, t.project_id, t.category_id, t.account_id,
       ${n(p.net)}, ${n(p.vat)}, ${n(p.wh)}, 'monthly', t.tx_date, ${p.count}, '${kindOf2(p.desc)}', 'active',
       'Από το Επιχειρησιακό Αρχείο (γραμμή Κινήσεων ${p.row}).'
from transactions t where t.legacy_excel_id = 'kiniseis-row-${p.row}'
on conflict (id) do nothing;

update transactions t set plan_id = p.id, installment_no = 1
from installment_plans p
where p.id = ${q(uuid5("plan:" + p.row))} and t.legacy_excel_id = 'kiniseis-row-${p.row}' and t.plan_id is null;

select * from regenerate_plan(${q(uuid5("plan:" + p.row))});\n`,
      );
    }
    if (p.paid > 0) {
      plans.push(
        `update transactions t set status = 'paid',
  paid_on = case when t.installment_no <= ${p.base} then ${q(openingDate)}::date
                 else greatest(t.due_date, ${q(dayAfterOpening)}::date) end
from installment_plans p
where t.plan_id = p.id and ${planMatch} and t.installment_no <= ${p.paid};\n`,
      );
    }
  }
  plans.push("commit;");
  const plansOut = path.join(path.dirname(out), "0300_workbook_plans.sql");
  fs.writeFileSync(plansOut, plans.join("\n"));

  console.log(`Έγραψα ${out}`);
  console.log(`  έργα ${Object.keys(projects).length} · κατηγορίες ${Object.keys(categories).length} · λογαριασμοί ${Object.keys(accounts).length} · επαφές ${Object.keys(contactsByName).length} · κινήσεις ${txCount}`);
  console.log(`  πληρωμένα έσοδα ${round2(totals.income)} · πληρωμένα έξοδα ${round2(totals.expense)} · ημ/νία υπολοίπων έναρξης ${openingDate}`);
  console.log(`  καθημερινά σε μετρητά ${dailyCount} γραμμές, ${round2(dailyTotal)} € · επαναλαμβανόμενα ${recurring.length} → ${plansOut}`);
  for (const [label, set] of [["έργα χωρίς αντιστοίχιση", report.unmappedProjects], ["κατηγορίες χωρίς αντιστοίχιση", report.unmappedCategories], ["λογαριασμοί χωρίς αντιστοίχιση", report.unmappedAccounts]]) {
    if (set.size) console.log(`  ${label}: ${[...set].join(", ")}`);
  }
  for (const s of report.skipped) console.log(`  παραλείφθηκε ${s}`);
}

module.exports = { loadWorkbook, cell, categoryCode, afmOrNull, round2 };

